My Express API returns a 500 on POST /login when the request body is empty.
Here is the handler — can you find the bug and fix it?

// src/routes/auth.js
const express = require('express');
const router = express.Router();
const { findUserByEmail, verifyPassword, signToken } = require('../services/users');

router.post('/login', async (req, res) => {
  const { email, password } = req.body;

  const user = await findUserByEmail(email.toLowerCase());
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const ok = await verifyPassword(password, user.passwordHash);
  if (!ok) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  return res.json({ token: signToken(user.id) });
});

module.exports = router;
